import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
   .version 8.0
   .target sm_89
   .address_size 64
   .visible .entry layernorm_affine_fwd(
       .param .u64 x_ptr,
       .param .u64 w_ptr,
       .param .u64 b_ptr,
       .param .u64 y_ptr,
       .param .u32 batch_size,
       .param .u32 S_total,
       .param .f32 eps_param
   )
   {
       .reg .pred   %p0, %p1, %p2;
       .reg .b32    %r_tid, %r_bid, %r_S, %r_i, %r_stride, %r_tmp, %cnt, %cnt2, %cntsum;
       .reg .b64    %x, %w, %b, %y, %x_base, %y_base, %addr, %off64, %byte_off, %tmp64, %saddr, %saddr2, %sbase, %sbase2, %off2, %sbase3, %saddr3, %saddr3b;
       .reg .f32    %sum, %sumsq, %val, %val2, %mean, %m2, %Sf, %var, %vareps, %std, %invstd, %eps;
       .reg .f32    %xv, %wv, %bv, %t, %yv, %delta, %delta2, %cntf, %cnt2f, %cntsumf, %ratio, %kterm;
       .shared .align 4 .b32 sh_sum[256];
       .shared .align 4 .b32 sh_sumsq[256];
       .shared .align 4 .b32 sh_cnt[256];
       // Load parameters
       ld.param.u64 %x, [x_ptr];
       ld.param.u64 %w, [w_ptr];
       ld.param.u64 %b, [b_ptr];
       ld.param.u64 %y, [y_ptr];
       ld.param.u32 %r_S, [S_total];
       ld.param.f32 %eps, [eps_param];
       // Thread/block info
       mov.u32 %r_tid, %tid.x;
       mov.u32 %r_bid, %ctaid.x;
       mov.u32 %r_stride, %ntid.x;
       // Compute base offsets for this sample
       mul.wide.u32 %tmp64, %r_S, %r_bid;     // elements offset = S * blockIdx.x
       shl.b64 %byte_off, %tmp64, 2;          // bytes = elements * 4
       add.s64 %x_base, %x, %byte_off;
       add.s64 %y_base, %y, %byte_off;
       // Initialize Welford partials
       mov.f32 %mean, 0f00000000;
       mov.f32 %m2,   0f00000000;
       mov.u32 %cnt,  0;
       // First pass: Welford per-thread accumulation
       mov.u32 %r_i, %r_tid;
   L_sum_loop:
       setp.ge.u32 %p0, %r_i, %r_S;
       @%p0 bra L_after_sum;
       mul.wide.u32 %off64, %r_i, 4;
        add.s64 %addr, %x_base, %off64;
       ld.global.f32 %val, [%addr];
       add.u32 %cnt, %cnt, 1;
       sub.f32 %delta, %val, %mean;
       cvt.rn.f32.u32 %cntf, %cnt;
       div.rn.f32 %delta2, %delta, %cntf;
       add.f32 %mean, %mean, %delta2;
       sub.f32 %delta2, %val, %mean;
       fma.rn.f32 %m2, %delta, %delta2, %m2;
       add.u32 %r_i, %r_i, %r_stride;
       bra L_sum_loop;
   L_after_sum:
       // Write Welford triples to shared memory
       mul.wide.u32 %off64, %r_tid, 4;
        mov.u64 %sbase,  sh_sum;
        mov.u64 %sbase2, sh_sumsq;
        mov.u64 %sbase3, sh_cnt;
       add.s64 %saddr,  %sbase,  %off64;
       st.shared.f32 [%saddr], %mean;
       add.s64 %saddr2, %sbase2, %off64;
       st.shared.f32 [%saddr2], %m2;
       add.s64 %saddr3, %sbase3, %off64;
       st.shared.u32 [%saddr3], %cnt;
       bar.sync 0;
       // Reduction in shared memory (assumes blockDim.x == 256)
       // Step 128
       setp.lt.u32 %p1, %r_tid, 128;
       @%p1 add.s64 %off2, %off64, 512;
       @%p1 add.s64 %saddr,  %sbase,  %off64;
       @%p1 ld.shared.f32 %mean, [%saddr];           // mean1
       @%p1 add.s64 %saddr2, %sbase,  %off2;
       @%p1 ld.shared.f32 %val,  [%saddr2];           // mean2
       @%p1 add.s64 %saddr,  %sbase2, %off64;
       @%p1 ld.shared.f32 %m2,   [%saddr];            // m2_1
       @%p1 add.s64 %saddr2, %sbase2, %off2;
       @%p1 ld.shared.f32 %val2, [%saddr2];           // m2_2
       @%p1 add.s64 %saddr3,  %sbase3, %off64;
       @%p1 ld.shared.u32 %cnt,  [%saddr3];           // cnt1
       @%p1 add.s64 %saddr3b, %sbase3, %off2;
       @%p1 ld.shared.u32 %cnt2, [%saddr3b];          // cnt2
       @%p1 add.u32 %cntsum, %cnt, %cnt2;
       @%p1 setp.ne.u32 %p0, %cntsum, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;         // mean2 - mean1
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf; // cnt2 / (cnt1+cnt2)
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;      // delta^2
       @%p2 mul.f32 %kterm, %kterm, %cntf;       // delta^2 * cnt1
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2; // + delta^2 * cnt1 * (cnt2/cntsum)
       @%p2 add.f32 %m2, %m2, %val2;             // + m2_2
       @%p1 add.s64 %saddr, %sbase, %off64;
       @%p1 st.shared.f32 [%saddr], %mean;
       @%p1 add.s64 %saddr, %sbase2, %off64;
       @%p1 st.shared.f32 [%saddr], %m2;
       @%p1 add.s64 %saddr3, %sbase3, %off64;
       @%p1 st.shared.u32 [%saddr3], %cntsum;
       bar.sync 0;
       // Step 64
       setp.lt.u32 %p1, %r_tid, 64;
       @%p1 add.s64 %off2, %off64, 256;
       @%p1 add.s64 %saddr,  %sbase,  %off64;
       @%p1 ld.shared.f32 %mean, [%saddr];
       @%p1 add.s64 %saddr2, %sbase,  %off2;
       @%p1 ld.shared.f32 %val,  [%saddr2];
       @%p1 add.s64 %saddr,  %sbase2, %off64;
       @%p1 ld.shared.f32 %m2,   [%saddr];
       @%p1 add.s64 %saddr2, %sbase2, %off2;
       @%p1 ld.shared.f32 %val2, [%saddr2];
       @%p1 add.s64 %saddr3,  %sbase3, %off64;
       @%p1 ld.shared.u32 %cnt,  [%saddr3];
       @%p1 add.s64 %saddr3b, %sbase3, %off2;
       @%p1 ld.shared.u32 %cnt2, [%saddr3b];
       @%p1 add.u32 %cntsum, %cnt, %cnt2;
       @%p1 setp.ne.u32 %p0, %cntsum, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p1 add.s64 %saddr, %sbase, %off64;
       @%p1 st.shared.f32 [%saddr], %mean;
       @%p1 add.s64 %saddr, %sbase2, %off64;
       @%p1 st.shared.f32 [%saddr], %m2;
       @%p1 add.s64 %saddr3, %sbase3, %off64;
       @%p1 st.shared.u32 [%saddr3], %cntsum;
       bar.sync 0;
       // Step 32
       setp.lt.u32 %p1, %r_tid, 32;
       @%p1 add.s64 %off2, %off64, 128;
       @%p1 add.s64 %saddr,  %sbase,  %off64;
       @%p1 ld.shared.f32 %mean, [%saddr];
       @%p1 add.s64 %saddr2, %sbase,  %off2;
       @%p1 ld.shared.f32 %val,  [%saddr2];
       @%p1 add.s64 %saddr,  %sbase2, %off64;
       @%p1 ld.shared.f32 %m2,   [%saddr];
       @%p1 add.s64 %saddr2, %sbase2, %off2;
       @%p1 ld.shared.f32 %val2, [%saddr2];
       @%p1 add.s64 %saddr3,  %sbase3, %off64;
       @%p1 ld.shared.u32 %cnt,  [%saddr3];
       @%p1 add.s64 %saddr3b, %sbase3, %off2;
       @%p1 ld.shared.u32 %cnt2, [%saddr3b];
       @%p1 add.u32 %cntsum, %cnt, %cnt2;
       @%p1 setp.ne.u32 %p0, %cntsum, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p1 add.s64 %saddr, %sbase, %off64;
       @%p1 st.shared.f32 [%saddr], %mean;
       @%p1 add.s64 %saddr, %sbase2, %off64;
       @%p1 st.shared.f32 [%saddr], %m2;
       @%p1 add.s64 %saddr3, %sbase3, %off64;
       @%p1 st.shared.u32 [%saddr3], %cntsum;
       bar.sync 0;
       // Step 16
       setp.lt.u32 %p1, %r_tid, 16;
       @%p1 add.s64 %off2, %off64, 64;
       @%p1 add.s64 %saddr,  %sbase,  %off64;
       @%p1 ld.shared.f32 %mean, [%saddr];
       @%p1 add.s64 %saddr2, %sbase,  %off2;
       @%p1 ld.shared.f32 %val,  [%saddr2];
       @%p1 add.s64 %saddr,  %sbase2, %off64;
       @%p1 ld.shared.f32 %m2,   [%saddr];
       @%p1 add.s64 %saddr2, %sbase2, %off2;
       @%p1 ld.shared.f32 %val2, [%saddr2];
       @%p1 add.s64 %saddr3,  %sbase3, %off64;
       @%p1 ld.shared.u32 %cnt,  [%saddr3];
       @%p1 add.s64 %saddr3b, %sbase3, %off2;
       @%p1 ld.shared.u32 %cnt2, [%saddr3b];
       @%p1 add.u32 %cntsum, %cnt, %cnt2;
       @%p1 setp.ne.u32 %p0, %cntsum, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p1 add.s64 %saddr, %sbase, %off64;
       @%p1 st.shared.f32 [%saddr], %mean;
       @%p1 add.s64 %saddr, %sbase2, %off64;
       @%p1 st.shared.f32 [%saddr], %m2;
       @%p1 add.s64 %saddr3, %sbase3, %off64;
       @%p1 st.shared.u32 [%saddr3], %cntsum;
       bar.sync 0;
       // Step 8
       setp.lt.u32 %p1, %r_tid, 8;
       @%p1 add.s64 %off2, %off64, 32;
       @%p1 add.s64 %saddr,  %sbase,  %off64;
       @%p1 ld.shared.f32 %mean, [%saddr];
       @%p1 add.s64 %saddr2, %sbase,  %off2;
       @%p1 ld.shared.f32 %val,  [%saddr2];
       @%p1 add.s64 %saddr,  %sbase2, %off64;
       @%p1 ld.shared.f32 %m2,   [%saddr];
       @%p1 add.s64 %saddr2, %sbase2, %off2;
       @%p1 ld.shared.f32 %val2, [%saddr2];
       @%p1 add.s64 %saddr3,  %sbase3, %off64;
       @%p1 ld.shared.u32 %cnt,  [%saddr3];
       @%p1 add.s64 %saddr3b, %sbase3, %off2;
       @%p1 ld.shared.u32 %cnt2, [%saddr3b];
       @%p1 add.u32 %cntsum, %cnt, %cnt2;
       @%p1 setp.ne.u32 %p0, %cntsum, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p1 add.s64 %saddr, %sbase, %off64;
       @%p1 st.shared.f32 [%saddr], %mean;
       @%p1 add.s64 %saddr, %sbase2, %off64;
       @%p1 st.shared.f32 [%saddr], %m2;
       @%p1 add.s64 %saddr3, %sbase3, %off64;
       @%p1 st.shared.u32 [%saddr3], %cntsum;
       bar.sync 0;
       // Step 4
       setp.lt.u32 %p1, %r_tid, 4;
       @%p1 add.s64 %off2, %off64, 16;
       @%p1 add.s64 %saddr,  %sbase,  %off64;
       @%p1 ld.shared.f32 %mean, [%saddr];
       @%p1 add.s64 %saddr2, %sbase,  %off2;
       @%p1 ld.shared.f32 %val,  [%saddr2];
       @%p1 add.s64 %saddr,  %sbase2, %off64;
       @%p1 ld.shared.f32 %m2,   [%saddr];
       @%p1 add.s64 %saddr2, %sbase2, %off2;
       @%p1 ld.shared.f32 %val2, [%saddr2];
       @%p1 add.s64 %saddr3,  %sbase3, %off64;
       @%p1 ld.shared.u32 %cnt,  [%saddr3];
       @%p1 add.s64 %saddr3b, %sbase3, %off2;
       @%p1 ld.shared.u32 %cnt2, [%saddr3b];
       @%p1 add.u32 %cntsum, %cnt, %cnt2;
       @%p1 setp.ne.u32 %p0, %cntsum, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p1 add.s64 %saddr, %sbase, %off64;
       @%p1 st.shared.f32 [%saddr], %mean;
       @%p1 add.s64 %saddr, %sbase2, %off64;
       @%p1 st.shared.f32 [%saddr], %m2;
       @%p1 add.s64 %saddr3, %sbase3, %off64;
       @%p1 st.shared.u32 [%saddr3], %cntsum;
       bar.sync 0;
       // Step 2
       setp.lt.u32 %p1, %r_tid, 2;
       @%p1 add.s64 %off2, %off64, 8;
       @%p1 add.s64 %saddr,  %sbase,  %off64;
       @%p1 ld.shared.f32 %mean, [%saddr];
       @%p1 add.s64 %saddr2, %sbase,  %off2;
       @%p1 ld.shared.f32 %val,  [%saddr2];
       @%p1 add.s64 %saddr,  %sbase2, %off64;
       @%p1 ld.shared.f32 %m2,   [%saddr];
       @%p1 add.s64 %saddr2, %sbase2, %off2;
       @%p1 ld.shared.f32 %val2, [%saddr2];
       @%p1 add.s64 %saddr3,  %sbase3, %off64;
       @%p1 ld.shared.u32 %cnt,  [%saddr3];
       @%p1 add.s64 %saddr3b, %sbase3, %off2;
       @%p1 ld.shared.u32 %cnt2, [%saddr3b];
       @%p1 add.u32 %cntsum, %cnt, %cnt2;
       @%p1 setp.ne.u32 %p0, %cntsum, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p1 add.s64 %saddr, %sbase, %off64;
       @%p1 st.shared.f32 [%saddr], %mean;
       @%p1 add.s64 %saddr, %sbase2, %off64;
       @%p1 st.shared.f32 [%saddr], %m2;
       @%p1 add.s64 %saddr3, %sbase3, %off64;
       @%p1 st.shared.u32 [%saddr3], %cntsum;
       bar.sync 0;
       // Step 1
       setp.lt.u32 %p1, %r_tid, 1;
       @%p1 add.s64 %off2, %off64, 4;
       @%p1 add.s64 %saddr,  %sbase,  %off64;
       @%p1 ld.shared.f32 %mean, [%saddr];
       @%p1 add.s64 %saddr2, %sbase,  %off2;
       @%p1 ld.shared.f32 %val,  [%saddr2];
       @%p1 add.s64 %saddr,  %sbase2, %off64;
       @%p1 ld.shared.f32 %m2,   [%saddr];
       @%p1 add.s64 %saddr2, %sbase2, %off2;
       @%p1 ld.shared.f32 %val2, [%saddr2];
       @%p1 add.s64 %saddr3,  %sbase3, %off64;
       @%p1 ld.shared.u32 %cnt,  [%saddr3];
       @%p1 add.s64 %saddr3b, %sbase3, %off2;
       @%p1 ld.shared.u32 %cnt2, [%saddr3b];
       @%p1 add.u32 %cntsum, %cnt, %cnt2;
       @%p1 setp.ne.u32 %p0, %cntsum, 0;
       and.pred %p2, %p1, %p0;
       @%p2 cvt.rn.f32.u32 %cntf, %cnt;
       @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
       @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
       @%p2 sub.f32 %delta, %val, %mean;
       @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
       @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
       @%p2 mul.f32 %kterm, %delta, %delta;
       @%p2 mul.f32 %kterm, %kterm, %cntf;
       @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
       @%p2 add.f32 %m2, %m2, %val2;
       @%p1 add.s64 %saddr, %sbase, %off64;
       @%p1 st.shared.f32 [%saddr], %mean;
       @%p1 add.s64 %saddr, %sbase2, %off64;
       @%p1 st.shared.f32 [%saddr], %m2;
       @%p1 add.s64 %saddr3, %sbase3, %off64;
       @%p1 st.shared.u32 [%saddr3], %cntsum;
       bar.sync 0;
       // Compute mean and invstd (thread 0) from Welford totals
       setp.eq.u32 %p0, %r_tid, 0;
       @%p0 ld.shared.f32 %mean, [sh_sum];
       @%p0 ld.shared.f32 %m2, [sh_sumsq];
       @%p0 cvt.rn.f32.u32 %Sf, %r_S;
       @%p0 div.rn.f32 %var, %m2, %Sf;          // population variance
       @%p0 max.f32 %var, %var, 0f00000000;
       @%p0 add.f32 %vareps, %var, %eps;
       @%p0 sqrt.rn.f32 %std, %vareps;
       @%p0 rcp.rn.f32 %invstd, %std;
       @%p0 st.shared.f32 [sh_sum], %mean;
       @%p0 st.shared.f32 [sh_sumsq], %invstd;
       bar.sync 0;
       // Load broadcasted mean and invstd
       ld.shared.f32 %mean, [sh_sum];
       ld.shared.f32 %invstd, [sh_sumsq];
       // Second pass: normalize, scale (weight), and shift (bias)
       mov.u32 %r_i, %r_tid;
   L_norm_loop:
