class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float32))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 is supported"
        assert x.is_contiguous(), "Input must be contiguous"
        assert tuple(x.shape[-len(self.normalized_shape):]) == self.normalized_shape, "Shape mismatch"

        # Determine number of samples (collapse leading dimensions)
        norm_elems = 1
        for d in self.normalized_shape:
            norm_elems *= int(d)
        total_elems = x.numel()
        assert total_elems % norm_elems == 0
        batch = total_elems // norm_elems

        # Ensure parameters are ready
        w = self.weight
        b = self.bias
        assert w.is_cuda and b.is_cuda, "Parameters must be on CUDA device"
        assert w.is_contiguous() and b.is_contiguous(), "Parameters must be contiguous"
        assert w.numel() == norm_elems and b.numel() == norm_elems, "Parameter size mismatch"

        y = torch.empty_like(x)

        module = _get_ptx_module()
        module.launch(
            "layernorm_affine_fwd",
            grid=(int(batch), 1, 1),
            block=(256, 1, 1),
            arguments=[x, w, b, y, u32(int(batch)), u32(int(norm_elems)), f32(float(self.eps))],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
