       @%p1 st.shared.f32 [%saddr], %m2;
       @%p1 add.s64 %saddr3, %sbase3, %off64;
       @%p1 st.shared.u32 [%saddr3], %cntsum;
       bar.sync 0;
       // Compute mean and invstd (thread 0) from Welford totals
       setp.eq.u32 %p0, %r_tid, 0;
       @%p0 ld.shared.f32 %mean, [sh_sum];
       @%p0 ld.shared.f32 %m2, [sh_sumsq];
       @%p0 cvt.rn.f32.u32 %Sf, %r_S;
       @%p0 div.rn.f32 %var, %m2, %Sf;          // population variance
       @%p0 max.f32 %var, %var, 0f00000000;
       @%p0 add.f32 %vareps, %var, %eps;
       @%p0 sqrt.rn.f32 %std, %vareps;
       @%p0 rcp.rn.f32 %invstd, %std;
       @%p0 st.shared.f32 [sh_sum], %mean;
       @%p0 st.shared.f32 [sh_sumsq], %invstd;
       bar.sync 0;
       // Load broadcasted mean and invstd
       ld.shared.f32 %mean, [sh_sum];
       ld.shared.f32 %invstd, [sh_sumsq];
       // Second pass: normalize, scale (weight), and shift (bias)
       mov.u32 %r_i, %r_tid;
   L_norm_loop:
       setp.ge.u32 %p0, %r_i, %r_S;
       @%p0 bra L_done;
       mul.wide.u32 %off64, %r_i, 4;
       add.s64 %addr, %x_base, %off64;
       ld.global.f32 %xv, [%addr];
       add.s64 %addr, %w, %off64;
       ld.global.f32 %wv, [%addr];
       add.s64 %addr, %b, %off64;
       ld.global.f32 %bv, [%addr];
       sub.f32 %t, %xv, %mean;
       mul.f32 %t, %t, %invstd;
       mul.f32 %t, %t, %wv;
       add.f32 %yv, %t, %bv;
       add.s64 %addr, %y_base, %off64;
       st.global.f32 [%addr], %yv;
       add.u32 %r_i, %r_i, %r_stride;
       bra L_norm_loop;
   L_done:
       ret;
   }
 """

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("layernorm_affine_fwd")

class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float32))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 is supported"
        assert x.is_contiguous(), "Input must be contiguous"
        assert tuple(x.shape[-len(self.normalized_shape):]) == self.normalized_shape, "Shape mismatch"

        # Determine number of samples (collapse leading dimensions)
        norm_elems = 1
        for d in self.normalized_shape:
            norm_elems *= int(d)
        total_elems = x.numel()
        assert total_elems % norm_elems == 0
        batch = total_elems // norm_elems

        # Ensure parameters are ready
        w = self.weight
        b = self.bias
        assert w.is_cuda and b.is_cuda, "Parameters must be on CUDA device"
        assert w.is_contiguous() and b.is_contiguous(), "Parameters must be contiguous"
        assert w.numel() == norm_elems and b.numel() == norm_elems, "Parameter size mismatch"

        y = torch.empty_like(x)

        module = _get_ptx_module()
        module.launch(
            "layernorm_affine_fwd",
            grid=(int(batch), 1, 1),
            block=(256, 1, 1),
            arguments=[x, w, b, y, u32(int(batch)), u32(int(norm_elems)), f32(float(self.eps))],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y
